figures.asymptoteSource:
// Distribution of a small random variable with its mean marked by a vertical rule.
// Two-argument size() fixes the output box, so the declared ratio is exact.
size(420,350);
pen ax = gray(0.35) + 1;
pen bar = gray(0.2) + 1.2;
pen m = red + 1.4;
real h[] = {0.1, 0.4, 0.2, 0.2, 0.1};
for (int i = 0; i < 5; ++i) {
  filldraw((i*1.6-0.6,0)--(i*1.6+0.6,0)--(i*1.6+0.6,h[i]*2.2)--(i*1.6-0.6,h[i]*2.2)--cycle, bar, bar);
}
draw((-1.1,0)--(7.1,0), ax);
draw((3.4,0)--(3.4,2.9), m);
label("mean", (3.4,2.9), N);
label("value", (3.0,-0.4), S);
label("probability", (7.1,0.4), E);

// Linearity diagram: two dependent variables whose means simply add.
// Two-argument size() fixes the output box, so the declared ratio is exact.
size(400,320);
pen t = gray(0.55) + 1;
pen ax = gray(0.35) + 1;
label("$X$", (0.2,2.4), W);
label("$Y$", (0.2,0.2), W);
label("$X+Y$", (4.9,1.3), E);
draw((0.6,2.2)--(2.3,1.3), t);
draw((0.6,0.4)--(2.3,1.3), t);
draw((2.3,1.3)--(4.5,1.3), t);
draw((5.4,0.5)--(7.8,0.5), ax);
label("means add even when the variables are dependent", (3.6,2.5), N);
